const ECHTVERSAND_FREIGESCHALTET = true;
const TESTADRESSE = "bewerbung@example.com";
const ANHANGNAME = "SHOWCASE-BEWERBER - Bewerbungsunterlagen.pdf";
const FINAL_ORDNER = "/showcase/files/final/";
const MIN_TEXT_ZEICHEN = 300;
const NL = String.fromCharCode(10);
const AUF = String.fromCharCode(123) + String.fromCharCode(123);
const ZU = String.fromCharCode(125) + String.fromCharCode(125);
const PLATZHALTER_DATUM = AUF + "DATUM" + ZU;

const LAUF_MODUS = ECHTVERSAND_FREIGESCHALTET ? "ECHT" : "TEST";

// Das Frontend uebergibt fuer genau diesen Lauf die bewusst ausgewaehlten IDs.
// Ohne Auswahl wird sicher abgebrochen; ein manueller Start kann dadurch nie
// versehentlich alle freigegebenen Bewerbungen versenden.
const AUSWAHL_ROH = String($env.M7_AUSWAHL_JSON || "").trim();
if (!AUSWAHL_ROH) { throw new Error("Keine Versandauswahl uebergeben. Es wird nichts gesendet."); }
let auswahlIds;
try { auswahlIds = JSON.parse(AUSWAHL_ROH); }
catch { throw new Error("Die Versandauswahl ist ungueltig. Es wird nichts gesendet."); }
if (!Array.isArray(auswahlIds) || auswahlIds.length === 0) {
  throw new Error("Die Versandauswahl ist leer. Es wird nichts gesendet.");
}
auswahlIds = auswahlIds.map(function(id) { return String(id || "").trim(); });
if (auswahlIds.some(function(id) { return !id; }) || new Set(auswahlIds).size !== auswahlIds.length) {
  throw new Error("Die Versandauswahl enthaelt leere oder doppelte IDs. Es wird nichts gesendet.");
}
const auswahl = new Set(auswahlIds);

const freigaben = $("M6_Freigabe laden").all();
const versand = $("M7_Versand laden").all();

for (const v of versand) {
  if (v.json && v.json.error) { throw new Error("M7_Versand konnte nicht gelesen werden. Ohne funktionierende Doppelversand-Sperre wird nichts gesendet. Fehler: " + String(v.json.error)); }
}

// Schluesselpruefung. Der Schluessel versand_schluessel ist die einzige Spalte,
// auf die die Schreibnodes matchen. Ist er bei einer relevanten Zeile leer oder
// passt er nicht zu stellen_id und modus, koennte ein Schreibvorgang die falsche
// Zeile treffen. Dann wird abgebrochen. Es wird nichts geraten und nichts repariert.
const schluesselMaengel = [];
for (const v of versand) {
  const j = v.json || {};
  const id = String(j.stellen_id || "").trim();
  const st = String(j.versand_status || "").trim().toUpperCase();
  if (!id || !st) { continue; }
  const wo = "Zeile " + (j.row_number === undefined ? "?" : j.row_number) + " (" + id + ")";
  const md = String(j.modus || "").trim().toUpperCase();
  const key = String(j.versand_schluessel || "").trim();
  if (!key) { schluesselMaengel.push(wo + ": versand_schluessel ist leer"); continue; }
  if (md !== "TEST" && md !== "ECHT") { schluesselMaengel.push(wo + ": modus ist " + (md || "leer") + ", erlaubt sind nur TEST und ECHT"); continue; }
  const erwartet = id + "|" + md;
  if (key !== erwartet) { schluesselMaengel.push(wo + ": versand_schluessel ist " + key + ", erwartet waere " + erwartet); }
}
if (schluesselMaengel.length > 0) {
  throw new Error("M7_Versand ist nicht schluessig. Ohne verlaesslichen Schluessel wird nichts gesendet und nichts automatisch repariert. Bitte die Zeilen von Hand pruefen: " + schluesselMaengel.join(" | "));
}

// Sperrlogik nach Modus.
// ECHT-Zeilen sperren immer, auch einen Testlauf.
// Zeilen ohne erkennbaren Modus sperren ebenfalls immer, der sichere Ausgang.
// TEST-Zeilen sperren nur einen weiteren Testlauf und niemals einen Echtversand.
const gesperrt = {};
for (const v of versand) {
  const j = v.json || {};
  const id = String(j.stellen_id || "").trim();
  const st = String(j.versand_status || "").trim().toUpperCase();
  const md = String(j.modus || "").trim().toUpperCase();
  if (!id || !st) { continue; }
  const sperrtDiesenLauf = (md === "TEST") ? (LAUF_MODUS === "TEST") : true;
  if (sperrtDiesenLauf) { gesperrt[id] = st + " / " + (md || "ohne Modus"); }
}

const kandidaten = [];
const maengel = [];

for (const zeile of freigaben) {
  const j = zeile.json || {};
  const id = String(j.stellen_id || "").trim();
  if (!id) { continue; }

  if (!auswahl.has(id)) { continue; }

  const entscheidung = String(j.entscheidung || "").trim().toUpperCase();
  const status = String(j.m6_status || "").trim().toUpperCase();
  if (entscheidung !== "JA") { continue; }
  if (status !== "FREIGEGEBEN") { continue; }
  if (gesperrt[id]) { continue; }

  const fehlt = [];

  const empfaenger = String(j.empfaenger_email || "").trim();
  if (!empfaenger) { fehlt.push("empfaenger_email fehlt"); }
  else if (empfaenger.indexOf("@") < 1 || empfaenger.indexOf(".") === -1 || empfaenger.indexOf(" ") !== -1) { fehlt.push("empfaenger_email unplausibel: " + empfaenger); }

  const betreff = String(j.betreff || "").trim();
  if (!betreff) { fehlt.push("betreff fehlt"); }

  const roh = String(j.anschreiben || "");
  if (!roh.trim()) { fehlt.push("anschreiben fehlt"); }

  const pdfPfad = String(j.final_pdf_pfad || "").trim();
  if (!pdfPfad) { fehlt.push("final_pdf_pfad fehlt, es gibt keine FINAL-PDF"); }
  else if (pdfPfad.indexOf(FINAL_ORDNER) !== 0) { fehlt.push("final_pdf_pfad zeigt nicht in den FINAL-Ordner: " + pdfPfad); }

  for (const spalte of Object.keys(j)) {
    const wert = (j[spalte] === null || j[spalte] === undefined) ? "" : String(j[spalte]);
    if (wert.indexOf(PLATZHALTER_DATUM) !== -1) { fehlt.push("Platzhalter DATUM steht noch in Spalte " + spalte); }
    else if (wert.indexOf(AUF) !== -1 && wert.indexOf(ZU) !== -1) { fehlt.push("unaufgeloester Platzhalter in Spalte " + spalte); }
  }

  let text = "";
  if (roh.trim()) {
    const teile = roh.split(NL);
    let ab = 0;
    if (teile[0].indexOf("Betreff:") === 0) {
      ab = 1;
      if (teile.length > 1 && teile[1].trim() === "") { ab = 2; }
    }
    text = teile.slice(ab).join(NL).trim();
    if (text.indexOf("Betreff:") !== -1) { fehlt.push("im Mailtext steht noch eine Betreff-Zeile"); }
    if (text.indexOf("Sehr geehrtes") !== 0) { fehlt.push("Mailtext beginnt nicht mit der Anrede"); }
    if (text.length < MIN_TEXT_ZEICHEN) { fehlt.push("Mailtext ist mit " + text.length + " Zeichen zu kurz"); }
  }

  if (fehlt.length > 0) { maengel.push(id + ": " + fehlt.join("; ")); continue; }

  const sendTo = ECHTVERSAND_FREIGESCHALTET ? empfaenger : TESTADRESSE;
  if (!ECHTVERSAND_FREIGESCHALTET && sendTo !== TESTADRESSE) { throw new Error("Testmodus verletzt. Abbruch."); }
  if (!sendTo) { throw new Error("Kein Empfaenger ermittelt. Abbruch."); }

  kandidaten.push({ json: {
    stellen_id: id,
    firma: String(j.firma || ""),
    empfaenger_echt: empfaenger,
    sendTo: sendTo,
    subject: betreff,
    message: text,
    message_zeichen: text.length,
    final_pdf_pfad: pdfPfad,
    anhang_datei: ANHANGNAME,
    modus: LAUF_MODUS,
    versand_schluessel: id + "|" + LAUF_MODUS
  } });
}

if (maengel.length === 0 && kandidaten.length !== auswahl.size) {
  const gefunden = new Set(kandidaten.map(function(k) { return String(k.json.stellen_id || ""); }));
  const fehlen = auswahlIds.filter(function(id) { return !gefunden.has(id); });
  throw new Error("Die Versandauswahl passt nicht mehr zum aktuellen Freigabestand. Nichts gesendet. Fehlend: " + fehlen.join(", "));
}

if (maengel.length > 0) {
  throw new Error("Pflichtpruefung fehlgeschlagen. Es wird nichts gesendet. " + maengel.join(" | "));
}

return kandidaten;

const ANHANGNAME = "SHOWCASE-BEWERBER - Bewerbungsunterlagen.pdf";
const MINDESTGROESSE = 1000000;

const items = $input.all();
const quelle = $("Kandidaten pruefen und Mail bauen").all();
if (items.length !== quelle.length) { throw new Error("Item-Anzahl passt nicht zusammen: " + items.length + " PDFs zu " + quelle.length + " Kandidaten. Nicht senden."); }

const raus = [];
for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const basis = quelle[i].json;
  if (!item.binary || !item.binary.data) { throw new Error("Kein Anhang geladen fuer " + basis.stellen_id + ". Nicht senden."); }
  const buffer = await this.helpers.getBinaryDataBuffer(i, "data");
  if (buffer.length < MINDESTGROESSE) { throw new Error("FINAL-PDF fuer " + basis.stellen_id + " ist nur " + buffer.length + " Bytes gross, unter 1 MB. Nicht senden."); }
  if (buffer.slice(0, 5).toString("utf8") !== "%PDF-") { throw new Error("Datei fuer " + basis.stellen_id + " ist keine PDF. Nicht senden."); }
  item.binary.data.fileName = ANHANGNAME;
  item.binary.data.fileExtension = "pdf";
  item.binary.data.mimeType = "application/pdf";
  item.json = Object.assign({}, basis, { anhang_datei: ANHANGNAME, anhang_bytes: buffer.length });
  raus.push(item);
}
return raus;

// Erst hier entsteht die datierte Endfassung - unmittelbar vor dem Versand.
// M6 hat nur inhaltlich freigegeben; zwischen Freigabe und Versand koennen Tage
// liegen, deshalb traegt die Bewerbung das Datum von HEUTE, nicht das der Freigabe.
//
// Dieser Knoten gibt die urspruenglichen Kandidatendaten unveraendert weiter.
// Die Rueckmeldung von M5B wird nur geprueft, nicht durchgereicht - sonst
// verloere der Versandpfad Empfaenger, Betreff und Mailtext.
//
// KORRIGIERT am 10.08.2026:
// Der Knoten las m5b_status, m5b_datum und m5b_pruefung direkt am Item.
// M5B liefert als Subworkflow aber die Zusammenfassung aus dem Knoten
// "M5B Zusammenfassung" zurueck - also status, modus, fertig, fehler,
// schreibfehler, alle_pruefungen_bestanden und dateien[]. m5b_status war
// daher immer undefined und die Pruefung schlug auch bei einem vollstaendig
// erfolgreichen FINAL-Lauf fehl. Es wurde nie versendet.
// Jetzt werden die tatsaechlich gelieferten Felder geprueft. Die Strenge
// bleibt erhalten: bei jedem Zweifel wird geworfen und nichts gesendet.

const kandidaten = $('Kandidaten pruefen und Mail bauen').all();
const ergebnisse = $input.all();

if (ergebnisse.length !== kandidaten.length) {
  throw new Error('M5B FINAL hat ' + ergebnisse.length + ' Ergebnisse fuer '
    + kandidaten.length + ' Kandidaten geliefert.');
}

const raus = [];
for (let i = 0; i < kandidaten.length; i++) {
  const k = kandidaten[i].json || {};
  const r = (ergebnisse[i] && ergebnisse[i].json) || {};
  const wer = k.firma || k.stellen_id;

  const status = String(r.status || '').toUpperCase();
  const fertig = Number(r.fertig || 0);
  const fehlerzahl = Number(r.fehler || 0) + Number(r.schreibfehler || 0);

  if (status !== 'ERFOLGREICH' || fertig < 1 || fehlerzahl > 0) {
    throw new Error('Endfassung fuer ' + wer + ' nicht erzeugt: status=' + (status || 'leer')
      + ', fertig=' + fertig + ', fehler=' + fehlerzahl
      + (r.abbruchgrund ? ', ' + r.abbruchgrund : '')
      + (r.fehlerdetails ? ', ' + r.fehlerdetails : ''));
  }

  if (String(r.modus || '').toUpperCase() !== 'FINAL') {
    throw new Error('Endfassung fuer ' + wer + ' wurde nicht im FINAL-Modus erzeugt: '
      + (r.modus || 'leer'));
  }

  if (r.alle_pruefungen_bestanden !== true) {
    throw new Error('Endfassung fuer ' + wer + ' hat die M5B-Pruefungen nicht bestanden.');
  }

  const datei = (Array.isArray(r.dateien) && r.dateien[0]) || null;
  if (!datei || !datei.datei) {
    throw new Error('Endfassung fuer ' + wer + ': M5B meldet keine erzeugte Datei.');
  }

  // Im FINAL-Lauf muss der Datums-Platzhalter ersetzt sein. M5B laesst einen
  // FINAL-Lauf nur dann als FERTIG durch, wenn das Datum tatsaechlich im
  // Seiteninhalt steht - dieses Flag ist der Beleg dafuer.
  if (datei.datum_platzhalter_vorhanden !== false) {
    throw new Error('Endfassung fuer ' + wer + ' enthaelt noch den Datums-Platzhalter.');
  }

  if (datei.seiten_2_bis_11_unveraendert !== true) {
    throw new Error('Endfassung fuer ' + wer + ': Seiten 2-11 wurden veraendert.');
  }

  // Die erzeugte Datei muss genau der Pfad sein, den M6 in M6_Freigabe
  // festgehalten hat - sonst haengt M7 spaeter die falsche PDF an.
  if (k.final_pdf_pfad && datei.datei !== k.final_pdf_pfad) {
    throw new Error('Endfassung fuer ' + wer + ' liegt unter ' + datei.datei
      + ', erwartet war ' + k.final_pdf_pfad + '.');
  }

  raus.push({ json: Object.assign({}, k, {
    _final_datei: datei.datei,
    _final_angehaengte_bytes: datei.angehaengte_bytes,
    _final_geprueft_am: r.ausgefuehrt_am
  }) });
}
return raus;
